type ExamSession = { startedAt: number; answers: Record<string, number>; written: Record<string, string> };
const examObjectives = units.flatMap(u => questionBank.filter(q => q.unit === u.id).slice(0, 4));
const examQuestions = [...examObjectives, ...subjectiveQuestions];
