  useEffect(() => { if (mode === 'exam' && session) { try { localStorage.setItem('trace-exam-v1', JSON.stringify({ ...session, answers: examAnswers, written })); } catch { /* In-memory exam remains usable. */ } } }, [session, examAnswers, written, mode]);
